import React from 'react';

const Templates = () => {
  const templates = [
    {
      id: 1,
      name: 'Minimal Resume',
      category: 'Resume',
      price: '$12',
      format: 'InDesign',
    },
    {
      id: 2,
      name: 'Brand Guidelines',
      category: 'Branding',
      price: '$45',
      format: 'InDesign',
    },
    {
      id: 3,
      name: 'Portfolio Layout',
      category: 'Editorial',
      price: '$28',
      format: 'InDesign',
    },
    {
      id: 4,
      name: 'Business Cards Set',
      category: 'Stationery',
      price: '$18',
      format: 'Illustrator',
    },
    {
      id: 5,
      name: 'Invoice Template',
      category: 'Business',
      price: '$15',
      format: 'InDesign',
    },
    {
      id: 6,
      name: 'Social Media Kit',
      category: 'Digital',
      price: '$35',
      format: 'Photoshop',
    },
  ];

  return (
    <div className="section" style={{ paddingTop: '120px' }}>
      <div className="container">
        {/* Header */}
        <div className="templates-header">
          <p className="section-label">Templates</p>
          <h1>Professional Templates</h1>
          <p className="text-lead" style={{ marginTop: 'var(--space-6)' }}>
            Carefully crafted design templates to help you create professional
            materials quickly. Fully editable and customizable.
          </p>
        </div>

        {/* Templates Grid */}
        <div className="templates-grid">
          {templates.map((template) => (
            <article key={template.id} className="template-card">
              <div className="template-preview">
                {template.category}
              </div>
              <p
                className="text-mono"
                style={{
                  fontSize: 'var(--text-xs)',
                  color: 'var(--color-gray-light)',
                  marginBottom: 'var(--space-2)',
                }}
              >
                {template.category} • {template.format}
              </p>
              <h3 className="template-name">{template.name}</h3>
              <p className="template-price">{template.price}</p>
            </article>
          ))}
        </div>

        {/* Info Section */}
        <div
          style={{
            marginTop: 'var(--space-16)',
            padding: 'var(--space-12)',
            border: '1px solid var(--color-border)',
            backgroundColor: 'var(--color-paper)',
          }}
        >
          <div className="grid grid-3">
            <div>
              <h4
                style={{
                  fontSize: 'var(--text-base)',
                  marginBottom: 'var(--space-3)',
                }}
              >
                Easy to Edit
              </h4>
              <p
                style={{
                  fontSize: 'var(--text-sm)',
                  color: 'var(--color-gray)',
                }}
              >
                All templates are fully editable with organized layers and
                clear documentation.
              </p>
            </div>
            <div>
              <h4
                style={{
                  fontSize: 'var(--text-base)',
                  marginBottom: 'var(--space-3)',
                }}
              >
                Commercial License
              </h4>
              <p
                style={{
                  fontSize: 'var(--text-sm)',
                  color: 'var(--color-gray)',
                }}
              >
                Use these templates for personal or commercial projects with our
                standard license.
              </p>
            </div>
            <div>
              <h4
                style={{
                  fontSize: 'var(--text-base)',
                  marginBottom: 'var(--space-3)',
                }}
              >
                Free Updates
              </h4>
              <p
                style={{
                  fontSize: 'var(--text-sm)',
                  color: 'var(--color-gray)',
                }}
              >
                Get free updates for life. When I improve a template, you get
                the new version.
              </p>
            </div>
          </div>
        </div>

        {/* Custom Templates CTA */}
        <div className="text-center" style={{ marginTop: 'var(--space-16)' }}>
          <p
            className="text-mono"
            style={{ color: 'var(--color-gray-light)', marginBottom: 'var(--space-4)' }}
          >
            Need something custom?
          </p>
          <p
            style={{
              fontSize: 'var(--text-xl)',
              maxWidth: '500px',
              margin: '0 auto var(--space-6)',
            }}
          >
            I also create custom templates tailored to your specific needs and
            brand guidelines.
          </p>
          <a href="mailto:hello@portfolio.com" className="btn">
            Request Custom Template
          </a>
        </div>
      </div>
    </div>
  );
};

export default Templates;
